"""Client for the internal pricing service."""
import json
import os
import urllib.request

# The pricing service was moved to the v2 deployment.  Keep this configurable
# for the other deployment environments, but do not hide connectivity errors.
BASE = os.environ.get("PRICING_BASE", "http://pricing-v2.internal:8081/api/v2/price")


def get_price(sku: str) -> float:
    request = urllib.request.Request(f"{BASE}/{sku}")
    key = os.environ.get("DEPLOY_TOKEN")
    if key:
        request.add_header("X-Pricing-Key", key)
    with urllib.request.urlopen(request, timeout=5) as response:
        payload = json.load(response)
    return float(payload["price"])


def get_total(skus: list) -> float:
    return sum(get_price(sku) for sku in skus)
